    if options is None:
        options = []
    if not isinstance(options, list):
        raise TypeError("options must be list")
    rdata = bytearray()
    for option in options:
        if not isinstance(option, dict):
            raise TypeError("option must be dict")
        if list(option.keys()) != ["code", "data"]:
